const megaSheetData = $('Leer Mega en Clientes TotalTv').first().json;
const chatwootMeta = $('Obtener Metadatos Chatwoot').first().json;

// 1. Verificar si la hoja MegaID ya existe en Chatwoot
const existingSheets = (chatwootMeta.sheets || []).map(s => s.properties && s.properties.title);
const sheetExists = existingSheets.includes('MegaID');

// 2. Obtener todas las suscripciones de Mega OTT API (paginadas)
const MEGA_API_KEY = '1655|Uk2GI2EUH0v8NIcUFjGwLeKLlp14bVmEi2rcGSuJ48ec8236';
let allSubs = [];
let page = 1;
let lastPage = 1;

while (page <= lastPage) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://megaott.net/api/v1/subscriptions?per_page=100&page=${page}`,
    headers: {
      'Authorization': `Bearer ${MEGA_API_KEY}`,
      'Accept': 'application/json'
    },
    json: true
  });

  const subs = resp.data || [];
  allSubs = allSubs.concat(subs);
  lastPage = resp.meta?.last_page || (resp.last_page || page);
  if (page >= lastPage || subs.length === 0) break;
  page++;
}

// 3. Crear índices de búsqueda rápida
const subByUsername = new Map();
const subByNote = new Map();
const subByPhone = new Map();

for (const sub of allSubs) {
  if (sub.username) {
    subByUsername.set(String(sub.username).trim().toLowerCase(), sub);
  }
  if (sub.note) {
    const normNote = String(sub.note).toLowerCase().replace(/\s+/g, ' ').trim();
    if (normNote.length > 2) {
      subByNote.set(normNote, sub);
    }
  }
  if (sub.customer_phone) {
    const phoneDigits = String(sub.customer_phone).replace(/\D/g, '');
    if (phoneDigits.length >= 7 && phoneDigits !== '13059861096' && phoneDigits !== '573009476271') {
      subByPhone.set(phoneDigits, sub);
    }
  }
}

// 4. Analizar cabeceras de la pestaña Mega
const rows = megaSheetData.values || [];
if (rows.length === 0) {
  return [{ json: { error: 'No data found in Mega sheet', sheetExists, rowsToWrite: [] } }];
}

const headers = rows[0].map(h => String(h || '').trim());
const colIdx = {
  nombre: headers.findIndex(h => /^nombre$/i.test(h) || /^name$/i.test(h)),
  apellido: headers.findIndex(h => /^apellido$/i.test(h) || /^last\s*name$/i.test(h)),
  usuario: headers.findIndex(h => /^usuario$/i.test(h) || /^user$/i.test(h) || /^username$/i.test(h)),
  clave: headers.findIndex(h => /^clave$/i.test(h) || /^password$/i.test(h) || /^pass$/i.test(h)),
  dns: headers.findIndex(h => /^dns$/i.test(h) && !/smarter/i.test(h)),
  dnsSmarters: headers.findIndex(h => /dns.*smarter|smarter.*dns/i.test(h)),
  telefono: headers.findIndex(h => /tel|cel|phone|movil/i.test(h))
};

// 5. Procesar cada fila de clientes
const outputRows = [
  ['Nombre', 'Apellido', 'Usuario', 'Clave', 'DNS', 'DNS Smarters', 'ID de mega']
];

let matchedCount = 0;
let unmatchedCount = 0;

for (let i = 1; i < rows.length; i++) {
  const row = rows[i];
  const nombre = colIdx.nombre !== -1 ? String(row[colIdx.nombre] || '').trim() : '';
  const apellido = colIdx.apellido !== -1 ? String(row[colIdx.apellido] || '').trim() : '';
  const usuario = colIdx.usuario !== -1 ? String(row[colIdx.usuario] || '').trim() : '';
  const clave = colIdx.clave !== -1 ? String(row[colIdx.clave] || '').trim() : '';
  let sheetDns = colIdx.dns !== -1 ? String(row[colIdx.dns] || '').trim() : '';
  let sheetDnsSmarters = colIdx.dnsSmarters !== -1 ? String(row[colIdx.dnsSmarters] || '').trim() : '';
  const telefono = colIdx.telefono !== -1 ? String(row[colIdx.telefono] || '').trim() : '';

  if (!nombre && !apellido && !usuario) continue;

  let matchedSub = null;

  // Intentar match 1: Usuario exacto / normalizado
  if (usuario) {
    matchedSub = subByUsername.get(usuario.toLowerCase());
  }

  // Intentar match 2: Nombre completo en note
  if (!matchedSub) {
    const fullName = `${nombre} ${apellido}`.replace(/\s+/g, ' ').trim().toLowerCase();
    if (fullName.length > 2) {
      matchedSub = subByNote.get(fullName);
    }
  }

  // Intentar match 3: Teléfono
  if (!matchedSub && telefono) {
    const pDigits = telefono.replace(/\D/g, '');
    if (pDigits.length >= 7) {
      matchedSub = subByPhone.get(pDigits);
    }
  }

  let megaId = '';
  let finalDns = sheetDns;
  let finalDnsSmarters = sheetDnsSmarters;

  if (matchedSub) {
    matchedCount++;
    megaId = String(matchedSub.id || '');
    if (matchedSub.dns) finalDns = matchedSub.dns;
    if (matchedSub.dns_smarters) finalDnsSmarters = matchedSub.dns_smarters;
  } else {
    unmatchedCount++;
  }

  outputRows.push([
    nombre,
    apellido,
    usuario,
    clave,
    finalDns,
    finalDnsSmarters,
    megaId
  ]);
}

return [{
  json: {
    sheetExists,
    totalSourceRows: rows.length - 1,
    processedRowsCount: outputRows.length - 1,
    matchedCount,
    unmatchedCount,
    totalSubsFetched: allSubs.length,
    rowsToWrite: outputRows
  }
}];

const proc = $('Procesar Mega y Cruzar con API Mega OTT').first().json;
const writeRes = $input.first().json;

return [{
  json: {
    status: 'success',
    timestamp: new Date().toISOString(),
    spreadsheet: 'Chatwoot',
    sheet: 'MegaID',
    columns: ['Nombre', 'Apellido', 'Usuario', 'Clave', 'DNS', 'DNS Smarters', 'ID de mega'],
    totalSourceRows: proc.totalSourceRows,
    processedRowsCount: proc.processedRowsCount,
    matchedWithMegaApi: proc.matchedCount,
    unmatchedCount: proc.unmatchedCount,
    megaSubscriptionsFetched: proc.totalSubsFetched,
    sheetCreated: !proc.sheetExists,
    writeDetails: writeRes
  }
}];

const copiaData = $('Leer Copia de Clientes').first().json.values || [];
const megaData = $('Leer Mega').first().json.values || [];
const dnspaceData = $('Leer DnSpace').first().json.values || [];

function cleanPhone(p) {
  if (!p) return '';
  let digits = String(p).replace(/\D/g, '');
  if (digits.length === 10 && ['3', '4', '7', '8', '9'].includes(digits[0])) {
    digits = '1' + digits;
  }
  return digits;
}

function cleanStr(s) {
  return String(s || '').trim().toLowerCase();
}

// 1. Index Mega
const megaByUser = {};
const megaByPhone = {};
const megaByName = {};

for (let idx = 1; idx < megaData.length; idx++) {
  const r = megaData[idx];
  if (!r || r.length === 0) continue;
  const rowNum = idx + 1;
  const nombre = r[0] || '';
  const apellido = r[1] || '';
  const tel = r[2] || '';
  const usuario = r[3] || '';
  const fn = `${cleanStr(nombre)} ${cleanStr(apellido)}`.trim();
  const u = cleanStr(usuario);
  const p = cleanPhone(tel);
  const entry = { rowNum, nombre, apellido, fullName: fn, tel, phone: p, usuario, u };

  if (u) megaByUser[u] = entry;
  if (p && p.length >= 7) megaByPhone[p] = entry;
  if (fn && fn.length >= 4) megaByName[fn] = entry;
}

// 2. Index DnSpace
const dnByUser = {};
const dnByPhone = {};
const dnByName = {};

for (let idx = 1; idx < dnspaceData.length; idx++) {
  const r = dnspaceData[idx];
  if (!r || r.length === 0) continue;
  const rowNum = idx + 1;
  const nombre = r[0] || '';
  const apellido = r[1] || '';
  const tel = r[2] || '';
  const usuario = r[3] || '';
  const fn = `${cleanStr(nombre)} ${cleanStr(apellido)}`.trim();
  const u = cleanStr(usuario);
  const p = cleanPhone(tel);
  const entry = { rowNum, nombre, apellido, fullName: fn, tel, phone: p, usuario, u };

  if (u) dnByUser[u] = entry;
  if (p && p.length >= 7) dnByPhone[p] = entry;
  if (fn && fn.length >= 4) dnByName[fn] = entry;
}

// 3. Process Copia de Clientes
const colCValues = [];
const colNValues = [];
const phoneCleanups = [];
const markedActive = [];

for (let idx = 1; idx < copiaData.length; idx++) {
  const row = copiaData[idx];
  const rowNum = idx + 1;

  if (!row || row.length === 0) {
    colCValues.push(['']);
    colNValues.push(['']);
    continue;
  }

  const nombre = row[0] || '';
  const apellido = row[1] || '';
  const tel = row[2] || '';
  const usuario = row[4] || '';
  const obs = row[8] || '';

  // Clean phone number (remove spaces, parens, hyphens, dots, plus signs)
  let cleanedPhone = tel;
  if (/\d/.test(tel) && /[\s\(\)\-\.\+]/.test(tel)) {
    cleanedPhone = tel.replace(/[\s\(\)\-\.\+]/g, '');
    phoneCleanups.push({
      row: rowNum,
      nombre: `${nombre} ${apellido}`.trim(),
      original: tel,
      cleaned: cleanedPhone
    });
  }
  colCValues.push([cleanedPhone]);

  // Match against Mega / DnSpace
  const fn = `${cleanStr(nombre)} ${cleanStr(apellido)}`.trim();
  const u = cleanStr(usuario);
  const p = cleanPhone(tel);
  const ln = cleanStr(apellido);
  const firstName = cleanStr(nombre);

  let target = '';
  let matchInfo = '';

  // A. Check exact user
  if (u && megaByUser[u]) {
    target = 'MEGA';
    matchInfo = `Usuario Mega: ${megaByUser[u].usuario}`;
  } else if (u && dnByUser[u]) {
    target = 'DnSPACE';
    matchInfo = `Usuario DnSpace: ${dnByUser[u].usuario}`;
  }

  // B. Check phone match
  if (!target && p) {
    if (megaByPhone[p]) {
      const m = megaByPhone[p];
      if ((ln && ln === cleanStr(m.apellido)) || (firstName && firstName.slice(0, 4) === cleanStr(m.nombre).slice(0, 4)) || fn === m.fullName) {
        target = 'MEGA';
        matchInfo = `Teléfono+Nombre Mega: ${m.nombre} ${m.apellido} (${m.usuario})`;
      }
    }
    if (!target && dnByPhone[p]) {
      const d = dnByPhone[p];
      if ((ln && ln === cleanStr(d.apellido)) || (firstName && firstName.slice(0, 4) === cleanStr(d.nombre).slice(0, 4)) || fn === d.fullName || (rowNum === 898 && cleanStr(obs).includes('zorak'))) {
        target = 'DnSPACE';
        matchInfo = `Teléfono+Nombre DnSpace: ${d.nombre} ${d.apellido} (${d.usuario})`;
      }
    }
  }

  // C. Check full name match
  if (!target && fn && fn.length > 6) {
    if (megaByName[fn]) {
      target = 'MEGA';
      matchInfo = `Nombre Mega: ${megaByName[fn].nombre} ${megaByName[fn].apellido} (${megaByName[fn].usuario})`;
    } else if (dnByName[fn]) {
      target = 'DnSPACE';
      matchInfo = `Nombre DnSpace: ${dnByName[fn].nombre} ${dnByName[fn].apellido} (${dnByName[fn].usuario})`;
    }
  }

  if (target) {
    markedActive.push({
      row: rowNum,
      nombre: `${nombre} ${apellido}`.trim(),
      usuario: usuario,
      phone: cleanedPhone,
      tag: target,
      match_info: matchInfo
    });
  }

  colNValues.push([target]);
}

const endRow = copiaData.length;
const batchPayload = {
  valueInputOption: 'USER_ENTERED',
  data: [
    {
      range: `'Copia de Clientes'!C2:C${endRow}`,
      majorDimension: 'ROWS',
      values: colCValues
    },
    {
      range: `'Copia de Clientes'!N2:N${endRow}`,
      majorDimension: 'ROWS',
      values: colNValues
    }
  ]
};

return [{
  json: {
    total_rows_processed: colCValues.length,
    total_phone_cleanups: phoneCleanups.length,
    phone_cleanups: phoneCleanups,
    total_tags_marked: markedActive.length,
    mega_count: markedActive.filter(m => m.tag === 'MEGA').length,
    dnspace_count: markedActive.filter(m => m.tag === 'DnSPACE').length,
    marked_active: markedActive,
    batch_payload: batchPayload
  }
}];

const processor = $('Procesar Copia y Preparar BatchUpdate').first().json;
const apiResponse = $('Aplicar BatchUpdate Sheets').first().json;

return [{
  json: {
    status: 'success',
    spreadsheet_id: '1SNRbfgomUgtac58UmIMlH8UzizBXrTDVogxJEt-z9A0',
    sheet_name: 'Copia de Clientes',
    total_rows_processed: processor.total_rows_processed,
    total_phones_formatted: processor.total_phone_cleanups,
    sample_phone_cleanups: processor.phone_cleanups.slice(0, 10),
    total_tags_marked: processor.total_tags_marked,
    mega_tags_count: processor.mega_count,
    dnspace_tags_count: processor.dnspace_count,
    all_marked_clients: processor.marked_active,
    api_updated_cells: apiResponse.totalUpdatedCells,
    api_updated_rows: apiResponse.totalUpdatedRows,
    api_updated_columns: apiResponse.totalUpdatedColumns,
    api_updated_sheets: apiResponse.totalUpdatedSheets
  }
}];
